{\small
\resumeSubHeadingListStart

\resumeSubheading
  {Machine Learning Engineer Intern}{May 2025 -- August 2025}
  {Ayar Labs}{Santa Clara, CA}
  \resumeItemListStart
    \resumeItem{Built an internal inspection workflow API in Ruby on Rails with clear OOP boundaries (controllers/services/models) because the previous endpoints mixed parsing, business rules, and formatting - operators got consistent report outputs.}
    \resumeItem{Implemented unit and integration tests for the inspection pipeline using RSpec around API response contracts and edge cases (missing fields, OCR mismatches, class-imbalance thresholds) - code reviews were faster because failures pointed.}
    \resumeItem{Reduced report-generation latency by profiling PostgreSQL request logs and query patterns, then adding targeted indexes and optimizing the data-fetch workflow to improve component performance.}
